interface SummonerPageProps {
  params: Promise<{
    username: string;
  }>;
}

export default async function SummonerPage({ params }: SummonerPageProps) {
  const { username } = await params;
  const summonerName = decodeURIComponent(username);

  return (
    <main className="flex min-h-screen flex-col items-center justify-center bg-zinc-950 px-4">
      <div className="w-full max-w-2xl flex flex-col gap-6">
        <h1 className="text-3xl font-bold text-white">
          {summonerName}
        </h1>
        <p className="text-zinc-400">Match history coming soon...</p>
      </div>
    </main>
  );
}